const KEY='volleyworld-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.version!==1)state=V.fresh()}catch{state=V.fresh()}let tab='home',round=Math.max(0,state.rounds.findIndex(r=>r.some(m=>!m.sets))),search='',editId=null,seasonView=null,editorSubmitted=false;
const $=id=>document.getElementById(id), names={CEV:'Châu Âu',NORCECA:'Bắc, Trung Mỹ & Caribe',AVC:'Châu Á & Đại Dương',CSV:'Nam Mỹ',CAVB:'Châu Phi'};
function save(){V.stampResults(state);window.Seasons?.capture(state);let stored=false;try{localStorage.setItem(window.Cloud?.storageKey()||KEY,JSON.stringify(state));stored=true;$('saved').textContent='● Đã lưu trên trình duyệt'}catch{$('saved').textContent='Không thể lưu · hãy xuất tiến độ'}window.Cloud?.changed(state);return stored}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}
function team(id){let t=V.get(id);return `<span class="team"><span class="flag">${t.flag}</span>${t.name}</span>`}
function formHtml(id,s=displayState()){const list=V.recentForm(s,id),label=list.length?list.map(x=>x.win?'Thắng':'Thua').join(', '):'Chưa có trận đã đấu';return `<span class="form-strip" role="img" aria-label="5 trận gần nhất, cũ đến mới: ${label}" title="5 trận đã hoàn thành gần nhất · cũ → mới">${Array.from({length:5-list.length},()=>'<span class="form-dot empty" aria-hidden="true">–</span>').join('')}${list.map(x=>`<span class="form-dot ${x.win?'form-win':'form-loss'}" aria-hidden="true" title="${x.win?'Thắng':'Thua'} ${V.get(x.opponent).name} ${x.score[0]}–${x.score[1]}">${x.win?'W':'L'}</span>`).join('')}</span>`}
function allMatches(){return [...state.rounds.flat(),...(state.playin||[]),...Object.values(state.bracket||{}).filter(Array.isArray).flat()]}
function findMatch(id){return allMatches().find(m=>m.id===id)}
function displayState(){return seasonView?.snapshot||state}
function isReadOnly(){return !!seasonView||V.complete(state)}
function navigate(t){if(t==='settings'&&!Seasons.canCustomize()){Seasons.customize();return}if(['home','history'].includes(t))seasonView=null;if(seasonView&&t==='league')t='table';tab=t;render()}
function render(){const s=displayState(),home=tab==='home',outer=['home','history','settings'].includes(tab),done=s.rounds.flat().filter(m=>m.sets).length,rd=s.rounds.filter(r=>r.every(m=>m.sets)).length,stage=V.complete(s)?'Hoàn tất':s.bracket?'Playoff':s.playin?'Vé vớt':'League phase';
$('homeHero').hidden=!home;$('stats').hidden=outer;$('nav').hidden=outer;$('seasonBar').hidden=home;
$('seasonBar').innerHTML=`<button onclick="navigate('home')">← Trang chủ</button><span class="badge">MÙA ${s.seasonNumber||1}${isReadOnly()?' · CHỈ XEM':''}</span>${seasonView?'<button onclick="navigate(\'history\')">Lịch sử mùa giải</button>':''}`;
$('stats').innerHTML=[['32','ĐỘI TUYỂN · 5 KHU VỰC'],[`${rd}<small style="font-size:15px;color:#859287"> / 31</small>`,'VÒNG LEAGUE HOÀN TẤT'],[done,'TRẬN LEAGUE ĐÃ ĐẤU'],[stage,'GIAI ĐOẠN HIỆN TẠI']].map(([n,l])=>`<div class="stat"><b>${n}</b><span>${l}</span></div>`).join('');
const items=seasonView?[['season-results','Kết quả mùa giải'],['table','BXH league'],['teams','Đội tham dự']]:[['table','Bảng xếp hạng'],['league','Lịch thi đấu'],['playoff','Vé vớt & Playoff'],['teams','32 đội tuyển'],['rules','Thể thức']];
$('nav').innerHTML=items.map(([id,n])=>`<button class="${tab===id?'active':''}" onclick="navigate('${id}')">${n}</button>`).join('');
$('heroAction').textContent=V.complete(state)?'Bắt đầu mùa giải mới →':V.started(state)?'Tiếp tục giải đấu →':'Bắt đầu giải đấu của bạn →';$('heroAction').onclick=()=>Seasons.start();$('heroSettings').onclick=()=>Seasons.customize();
if(home)Seasons.home();if(tab==='history')Seasons.history();if(tab==='season-results')Seasons.results();if(tab==='table')renderTable();if(tab==='league')renderLeague();if(tab==='playoff')renderPlayoff();if(tab==='teams')renderTeams();if(tab==='rules')renderRules();if(tab==='settings')Settings.render();}
function renderTable(){let rows=V.standings(displayState()),q=qualificationData();$('content').innerHTML=`<div class="section-head"><div><h2>League standings</h2><p class="sub">Thắng / thua → hiệu số set → hiệu số điểm → đối đầu → bốc thăm</p></div><div class="controls">${isReadOnly()?'':'<input class="search" placeholder="Tìm đội tuyển…" aria-label="Tìm đội tuyển" id="search">'}${isReadOnly()?'':`<button class="primary" onclick="navigate('league')">Thi đấu vòng tiếp theo →</button>`}</div></div><div class="legend"><span><i class="dot"></i>1–12: Vào thẳng playoff</span><span><i class="dot yellow"></i>13–20: Vòng vé vớt</span><span><i class="dot gray"></i>21–32: Bị loại sau league</span></div>${qualificationNews(q)}<div class="panel table-wrap"><table><thead><tr><th>#</th><th>ĐỘI TUYỂN</th><th>KHU VỰC</th><th>TRẬN</th><th>W</th><th>L</th><th>SET +/−</th><th>HS SET</th><th>ĐIỂM +/−</th><th>HS ĐIỂM</th></tr></thead><tbody id="rows"></tbody></table></div>`;const draw=()=>{$('rows').innerHTML=rows.map((t,i)=>({...t,pos:i+1})).filter(t=>t.name.toLowerCase().includes(search.toLowerCase())||t.id.toLowerCase().includes(search.toLowerCase())).map(t=>`<tr class="${t.pos<=12?'direct':t.pos<=20?'in':'out'}"><td>${t.pos}</td><td>${team(t.id)}${qualificationBadge(q?.teams[t.id])}</td><td><span class="badge">${t.region}</span></td><td>${t.w+t.l}</td><td><b>${t.w}</b></td><td>${t.l}</td><td>${t.sf} : ${t.sa}</td><td><b>${signed(t.sf-t.sa)}</b></td><td>${t.pf} : ${t.pa}</td><td>${signed(t.pf-t.pa)}</td></tr>`).join('')};if($('search')){$('search').value=search;$('search').oninput=e=>{search=e.target.value;draw()}}draw();}
function signed(n){return n>0?'+'+n:n}
function qualificationData(s=displayState()){return window.Qualification?.report(s)||null}
function qualificationBadge(t){if(!t)return '';const label=t.direct?'Chắc playoff trực tiếp':t.out?'Đã bị loại':t.playin?'Chắc dự vòng vé vớt':t.advance?'Chắc ít nhất vé vớt':t.noDirect?'Hết cơ hội vào thẳng':'Chưa chốt',kind=t.direct?'direct':t.out?'out':t.playin||t.advance?'advance':t.noDirect?'no-direct':'pending';return label?`<span class="qualification-badge q-${kind}">${label}</span>`:''}
function qualificationNews(q){if(!q||!q.rounds.length)return '';const messages=[['direct','Đã chắc suất playoff trực tiếp'],['advance','Đã chắc suất ít nhất tranh vé vớt'],['playin','Đã chắc chắn tham dự vòng vé vớt'],['noDirect','Đã hết cơ hội vào thẳng playoff; chưa bị xác nhận loại khỏi top 20'],['out','Đã chính thức bị loại khỏi cuộc đua top 20']];const events=messages.filter(([key])=>q.events[key].length);return `<section class="qualification-news panel" aria-label="Thông báo suất đi tiếp"><div class="qualification-heading"><span class="eyebrow">CUỘC ĐUA PLAYOFF</span><span class="badge">SAU VÒNG ${q.lastRound+1} · ${q.rounds.length}/31 VÒNG HOÀN TẤT</span></div>${events.length?events.map(([key,text])=>`<div class="qualification-event q-${key==='playin'?'advance':key}"><b>${text}</b><div class="qualification-names">${q.events[key].map(team).join('')}</div></div>`).join(''):'<p class="sub">Chưa có suất mới được xác nhận ở vòng vừa hoàn tất.</p>'}<details class="qualification-explain"><summary>Cách xác định chắc suất</summary><p>Chỉ xét các vòng đã hoàn tất, không tính điểm ở vòng còn dở. Kiểm tra cả lịch đối đầu còn lại, số trận thắng, hiệu số set và hiệu số điểm. Chỉ công bố khi chứng minh được; nếu còn vướng đối đầu hoặc chưa đủ bằng chứng thì giữ trạng thái chưa chốt. Khi league kết thúc, dùng đầy đủ luật xếp hạng của giải.</p><p>Sửa điểm cũ sẽ tính lại các suất. Vùng màu trong BXH thể hiện vị trí hiện tại; huy hiệu thể hiện suất đã chắc chắn.</p></details></section>`}
function qualificationEntries(q){if(!q)return '';const groups=[['direct','Vào thẳng playoff',12,'Chờ thứ hạng cuối cùng để chia seed.'],['playin','Đã ghi danh vòng vé vớt',8,'Chắc nằm trong hạng 13–20. Chờ thứ hạng cuối để ghép cặp.'],['pending','Chắc đi tiếp · chờ loại suất',null,'Đã chắc top 20. Chưa chốt suất trực tiếp hay vé vớt.']];return `<div class="qualification-entry-grid">${groups.map(([key,title,max,help])=>{const ids=V.ids(displayState()).filter(id=>key==='pending'?q.teams[id].advance&&!q.teams[id].direct&&!q.teams[id].playin:q.teams[id][key]);return `<section class="panel qualification-entry"><div class="qualification-heading"><h3>${title}</h3><span class="badge">${ids.length}${max?' / '+max:''}</span></div><p class="sub">${help}</p><div class="qualification-names">${ids.length?ids.map(team).join(''):'<span class="sub">Chưa có đội được xác nhận.</span>'}</div></section>`}).join('')}</div>`}
function isLocked(m){if(isReadOnly())return true;if(m.id.startsWith('L'))return !!state.playin;if(m.id.startsWith('P'))return !!state.bracket;let b=state.bracket;if(!b)return false;const next={R:'qf',Q:'sf',S:'final'};return !!b[next[m.id[0]]]?.length}
function card(m,label='',locked=false){locked=isLocked(m);let[a,b]=V.score(m),win=V.winner(m),seed=displayState().bracket?.seeds;return `<article class="match"><div class="match-top"><span>${label||'BEST OF FIVE'}</span><span>${m.sets?'HOÀN TẤT':'CHƯA ĐẤU'}</span></div>${[m.a,m.b].map((id,i)=>`<div class="side ${win===id?'win':''}"><span class="match-team-info">${team(id)}${formHtml(id)}</span>${seed&&seed[id]?`<span class="badge">S${seed[id]}</span>`:''}<span class="result">${m.sets?(i===0?a:b):'–'}</span></div>`).join('')}${m.sets?`<div class="sets">${m.sets.map((s,i)=>`S${i+1} ${s[0]}–${s[1]}`).join(' · ')}</div>`:''}${isReadOnly()?'':`<div class="match-actions">${!m.sets?`<button class="primary" onclick="simOne('${m.id}')">Mô phỏng</button>`:''}<button ${locked?'disabled':''} onclick="editMatch('${m.id}')">${m.sets?'Xem / sửa điểm':'Nhập điểm'}</button></div>`}</article>`}
function renderLeague(){$('content').innerHTML=`<div class="section-head"><div><h2>Lịch thi đấu league</h2><p class="sub">Vòng tròn một lượt · 496 trận · Phong độ: cũ → mới</p></div><div class="controls"><select aria-label="Chọn vòng" onchange="round=Number(this.value);renderLeague()">${state.rounds.map((r,i)=>`<option value="${i}" ${i===round?'selected':''}>Vòng ${i+1}${r.every(m=>m.sets)?' ✓':''}</option>`).join('')}</select><button onclick="simRound()" ${state.rounds[round].every(m=>m.sets)?'disabled':''}>Chạy vòng ${round+1}</button><button class="primary" onclick="simLeague()" ${V.leagueDone(state)?'disabled':''}>Chạy hết league</button></div></div><div class="progress"><i style="width:${state.rounds.flat().filter(m=>m.sets).length/496*100}%"></i></div><div style="height:20px"></div>${V.leagueDone(state)?`<div class="notice"><b>League đã kết thúc!</b> Top 12 đi tiếp; hạng 13–20 tranh 4 vé còn lại. <button onclick="navigate('playoff')">Đến vòng vé vớt →</button></div>`:''}${qualificationNews(qualificationData())}<div class="grid">${state.rounds[round].map(m=>card(m,`VÒNG ${round+1}`,!!state.playin)).join('')}</div><div class="section-head" style="margin-top:20px"><button ${round===0?'disabled':''} onclick="round--;renderLeague()">← Vòng trước</button><button ${round===30?'disabled':''} onclick="round++;renderLeague()">Vòng sau →</button></div>`;}
function simOne(id){if(!Seasons.editable())return;let m=findMatch(id);if(!m||m.sets)return;V.simulate(m);V.advance(state);save();render()}
function simRound(){if(!Seasons.editable())return;state.rounds[round].filter(m=>!m.sets).forEach(V.simulate);save();render();toast(`Đã hoàn tất vòng ${round+1}`)}
function simLeague(){if(!Seasons.editable())return;if(!confirm('Mô phỏng tất cả trận league chưa đấu? Kết quả đã có được giữ nguyên.'))return;state.rounds.flat().filter(m=>!m.sets).forEach(V.simulate);save();render();toast('League đã hoàn tất. Vòng vé vớt đã sẵn sàng!')}
function startPlayin(){if(!Seasons.editable())return;V.startPlayin(state);save();render()}
function drawBracket(){if(!Seasons.editable())return;V.draw(state);save();render();toast('Đã bốc thăm 4 nhánh. Nhánh đấu được giữ cố định!')}
function simStage(key){if(!Seasons.editable())return;state.bracket[key].filter(m=>!m.sets).forEach(V.simulate);V.advance(state);save();render()}
function renderPlayoff(){const s=displayState();if(isReadOnly()&&!s.playin){$('content').innerHTML='<div class="notice">Mùa này chưa có vòng vé vớt hoặc nhánh playoff.</div>';return}if(!V.leagueDone(s)){$('content').innerHTML=`<div class="notice"><span class="badge">CHẶNG TIẾP THEO</span><h2 style="margin-top:12px">Con đường đến chức vô địch</h2><p>Hoàn tất 31 vòng league để xác định 12 đội vào thẳng playoff và 8 đội tranh vé vớt.</p><button class="primary" onclick="navigate('league')">Tiếp tục league →</button></div>${qualificationNews(qualificationData(s))}${qualificationEntries(qualificationData(s))}<div class="rule-grid"><div class="panel rule"><h3>01 / Vòng vé vớt</h3><p>Hạng 13–20 · 13 vs 20, 14 vs 19, 15 vs 18, 16 vs 17. Bốn trận BO5, bốn vé đi tiếp.</p></div><div class="panel rule"><h3>02 / Playoff 16 đội</h3><p>Bốn nhánh, mỗi nhánh đủ seed 1–4. Bốc thăm một lần, sau đó đi theo nhánh đến chung kết.</p></div></div>`;return}if(!s.playin){$('content').innerHTML=`${qualificationNews(qualificationData(s))}${qualificationEntries(qualificationData(s))}<div class="notice"><h2>Đã xác định top 20</h2><p>12 đội đầu vào thẳng playoff. Tạo các cặp vé vớt theo thứ hạng league.</p><button class="primary" onclick="startPlayin()">Tạo vòng vé vớt →</button></div>`;return}const pDone=s.playin.every(m=>m.sets),b=s.bracket;let html=`<div class="section-head"><div><h2>Vòng vé vớt</h2><p class="sub">Hạng 13–20 · một trận BO5 loại trực tiếp</p></div>${isReadOnly()?'':!pDone?`<button class="primary" onclick="state.playin.filter(m=>!m.sets).forEach(V.simulate);save();render()">Chạy vòng vé vớt</button>`:!b?`<button class="primary" onclick="drawBracket()">Bốc thăm playoff →</button>`:'<span class="badge">ĐÃ HOÀN TẤT</span>'}</div><div class="grid">${s.playin.map((m,i)=>card(m,`HẠNG ${13+i} vs ${20-i}`,!!b)).join('')}</div>`;if(b){let champion=b.final[0]&&V.winner(b.final[0]);if(champion)html+=`<div class="podium" style="margin-top:25px"><div class="trophy">🏆</div><div class="eyebrow" style="color:#d6f46a">WORLD CHAMPION</div><h2>${team(champion)}</h2><p>Á quân: ${V.get(V.loser(b.final[0])).name}${b.bronze[0]?.sets?' · Hạng ba: '+V.get(V.winner(b.bronze[0])).name:' · Trận tranh hạng ba chưa hoàn tất'}</p></div>`;html+=`<div class="section-head" style="margin-top:32px"><div><h2>Đường đến ngôi vô địch</h2><p class="sub">Bốc thăm một lần · nhánh A–B gặp nhau ở bán kết 1, C–D ở bán kết 2</p></div></div><div class="bracket-scroll"><div class="bracket">`;for(const [key,title,cls]of [['r16','Vòng 16 đội',''],['qf','Tứ kết','qf'],['sf','Bán kết','sf'],['final','Chung kết','fin']]){html+=`<div class="bracket-col ${cls}"><div class="section-head"><h3>${title}</h3>${!isReadOnly()&&b[key].length&&b[key].some(m=>!m.sets)?`<button onclick="simStage('${key}')" style="padding:5px 8px;font-size:10px">Chạy vòng</button>`:''}</div>`;if(!b[key].length)html+=`<div class="placeholder">Chờ kết quả vòng trước</div>`;else for(let i=0;i<b[key].length;i++){if(key==='r16'&&i%2===0)html+=`<div class="branch-label">NHÁNH ${'ABCD'[i/2]}</div>`;html+=card(b[key][i],key==='r16'?`NHÁNH ${'ABCD'[Math.floor(i/2)]}`:title,Object.values(b).filter(Array.isArray).flat().some(m=>m.sets&&(m.a===V.winner(b[key][i])||m.b===V.winner(b[key][i]))&&m.id!==b[key][i].id&&m.id[0]!==b[key][i].id[0]));}if(key==='final'){html+=`<h3 class="bronze">Tranh hạng ba</h3>`;html+=b.bronze.length?card(b.bronze[0],'TRANH HẠNG BA'): '<div class="placeholder">Hai đội thua bán kết</div>'}html+='</div>'}html+='</div></div>'}$('content').innerHTML=html;}
function renderTeams(){$('content').innerHTML=`<div class="section-head"><div><h2>32 đội tuyển tham dự</h2><p class="sub">Danh sách đang dự giải · bộ BXH tham chiếu 13/10/2026</p></div><span class="badge">${Object.values(V.quotas(V.ids(displayState()))).join(' / ')}</span></div><div class="region-grid">${Object.entries(names).map(([r,n])=>`<div class="panel region-card"><span class="badge">${r} · ${V.participants(displayState()).filter(t=>t.region===r).length} SUẤT</span><h3 style="margin-top:12px">${n}</h3>${V.participants(displayState()).filter(t=>t.region===r).map(t=>`<div class="team"><span class="flag">${t.flag}</span>${t.name}<small>#${t.rank}</small></div>`).join('')}</div>`).join('')}</div><p class="sub" style="margin-top:20px">Nguồn dữ liệu ban đầu: <a href="https://www.volleyballer.jp/senior_world_ranking_men/" target="_blank" rel="noopener">bảng tổng hợp FIVB của Volleyballer</a>, ngày 13/10/2026. Bộ đội cố định cho mùa giả lập; không tự cập nhật trực tiếp. Nga được giữ theo bộ BXH đã chọn, không mô phỏng điều kiện tham dự thực tế. Sức mạnh mô phỏng dựa trên điểm BXH, có yếu tố ngẫu nhiên; không phải dự đoán chính thức.</p>`;}
function renderRules(){const rules=[['01 / Phân bổ suất','Giải luôn có 32 đội. Mặc định: CEV 14, NORCECA 6, AVC 5, CSV 5, CAVB 2; bạn có thể thay đổi số suất và chọn đội ở nút Tùy chỉnh thể thức ở trang chủ, trước khi mùa giải bắt đầu. Danh sách đội và dự phòng xếp theo BXH khu vực.'],['02 / League phase','Vòng tròn một lượt: 31 vòng × 16 trận = 496 trận. Mỗi đội gặp 31 đối thủ đúng một lần. Tất cả trận BO5, thắng 3 set để thắng trận.'],['03 / Xếp hạng','Xét số trận thắng giảm dần, số trận thua tăng dần, hiệu số set, hiệu số điểm. Nếu còn bằng nhau: số trận thắng đối đầu giữa các đội cùng nhóm bằng chỉ số; cuối cùng dùng thứ tự bốc thăm cố định từ đầu mùa. Không dùng điểm 3–2–1–0.'],['04 / Điểm số','Set 1–4 đến 25, set 5 đến 15, luôn cách biệt ít nhất 2 điểm. Hiệu số set = set thắng − set thua. Hiệu số điểm = điểm ghi − điểm chịu; ghi 140, chịu 120 là +20.'],['05 / Vé vớt','Top 12 vào thẳng playoff. Hạng 13–20 đấu BO5 loại trực tiếp: 13 vs 20, 14 vs 19, 15 vs 18, 16 vs 17. Hạng 21–32 bị loại.'],['06 / Seed & bốc thăm','Seed 1: hạng 1–4; seed 2: 5–8; seed 3: 9–12; seed 4: bốn đội thắng vé vớt. Mỗi nhánh A–D có đủ bốn seed. Vòng 16 đội: S1 vs S4 và S2 vs S3.'],['07 / Nhánh đấu cố định','Hai đội thắng vòng 16 trong cùng nhánh gặp nhau ở tứ kết. Thắng nhánh A gặp B, C gặp D ở bán kết. Không bốc thăm lại. Hai đội thắng vào chung kết, hai đội thua tranh hạng ba.'],['08 / Cách chơi & lưu','Mô phỏng từng trận, từng vòng hoặc toàn bộ league. Có thể nhập điểm từng set thủ công. Kết quả vòng trước bị khóa khi đã tạo vòng tiếp theo để giữ đúng nhánh. Tiến độ tự lưu trên trình duyệt; dùng Xuất / Nhập tiến độ để chuyển thiết bị.']];$('content').innerHTML=`<div class="section-head"><h2>Luật giải đấu</h2><span class="badge">CUSTOM WORLD CUP</span></div><div class="rule-grid">${rules.map(([h,p])=>`<div class="panel rule"><h3>${h}</h3><p>${p}</p></div>`).join('')}</div>`;}
function editMatch(id){if(!Seasons.editable())return;let m=findMatch(id);if(!m||isLocked(m))return;editId=id;editorSubmitted=false;$('editorTitle').textContent='Nhập kết quả trận đấu';$('editorScoreboard').innerHTML=[m.a,m.b].map((id,i)=>`<div class="editor-team-row"><span class="match-team-info">${team(id)}${formHtml(id,state)}</span><b class="live-set-score" id="liveScore${i}" hidden></b></div>`).join('');$('setInputs').innerHTML=`<div class="score-column-labels"><span>SET</span><span>${m.a}</span><span></span><span>${m.b}</span></div>`+Array.from({length:5},(_,i)=>`<div class="set-block" id="setBlock${i}"><div class="set-row"><label for="a${i}">Set ${i+1}</label><input aria-label="${V.get(m.a).name} set ${i+1}" aria-describedby="setError${i}" id="a${i}" type="number" min="0" step="1" inputmode="numeric" oninput="updateScoreEditor()" value="${m.sets?.[i]?.[0]??''}"><span>:</span><input aria-label="${V.get(m.b).name} set ${i+1}" aria-describedby="setError${i}" id="b${i}" type="number" min="0" step="1" inputmode="numeric" oninput="updateScoreEditor()" value="${m.sets?.[i]?.[1]??''}"></div><p class="set-error" id="setError${i}" role="alert" hidden></p></div>`).join('');updateScoreEditor();$('editor').showModal()}
function readScoreInputs(){return Array.from({length:5},(_,i)=>['a','b'].map(side=>{const input=$(side+i);return input.validity?.badInput?'invalid-number':input.value}))}
function updateScoreEditor(){const result=V.inspectScoreInputs(readScoreInputs());for(let side=0;side<2;side++){$('liveScore'+side).hidden=!result.hasPair;$('liveScore'+side).textContent=result.hasPair?String(result.score[side]):''}for(let i=0;i<5;i++){const message=editorSubmitted?result.errors[i]:'';$('setError'+i).textContent=message;$('setError'+i).hidden=!message;$('setBlock'+i).classList.toggle('set-invalid',!!message);for(const side of ['a','b'])$(side+i).setAttribute('aria-invalid',message?'true':'false')}return result}
$('scoreForm').onsubmit=e=>{e.preventDefault();if(!Seasons.editable())return;const m=findMatch(editId);if(!m||isLocked(m))return;editorSubmitted=true;const result=updateScoreEditor();if(!result.valid){const index=Math.max(0,result.errors.findIndex(Boolean)),side=result.focusSides[index]===1?'b':'a';$('setBlock'+index).scrollIntoView({block:'nearest',behavior:'smooth'});$(side+index).focus();return}m.sets=result.sets;V.advance(state);save();$('editor').close();render();toast('Đã lưu kết quả')};
async function exportSave(){try{const bundle=await Seasons.exportAll(),url=URL.createObjectURL(new Blob([JSON.stringify(bundle,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='volleyworld-cac-mua-giai.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message||'Chưa xuất được lịch sử.')}}
function validSave(s){return V.validState(s)}
$('import').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let data=JSON.parse(await f.text()),s=data.format==='volleyworld-seasons'?data.active:data;if(!validSave(s))throw Error();if(!confirm('Thay tiến độ hiện tại bằng file đã chọn?'))return;window.Cloud?.backupCurrent();if(data.format==='volleyworld-seasons')s=Seasons.importAll(data);state=V.ensureSeason(s);seasonView=null;window.Settings?.discard();round=Math.max(0,state.rounds.findIndex(r=>r.some(m=>!m.sets)));tab='home';save();render();toast('Đã khôi phục tiến độ')}catch{toast('File tiến độ không hợp lệ.')}e.target.value=''};
function resetGame(){Seasons.requestNew()}
save();render();
